def extract(context):
    wti = context.get('wti')
    wti_hist = context.get('wti_history', [])
    if wti and len(wti_hist) >= 4:
        return {'wti_momentum_4w': (wti - wti_hist[-4]) / wti_hist[-4] if wti_hist[-4] else 0}
